	vDst := reflect.ValueOf(n.dst).Elem()
	if vDst.Kind() == reflect.Pointer {
		if vDst.IsNil() {
			vDst.Set(reflect.New(vDst.Type().Elem()))
		}
		return convertAssign(vDst.Interface(), src)
	}

	return convertAssign(n.dst, src)
